// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 g) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);
        // target block is the block right after lock-in; roll to exactly that block
        vm.roll(block.number + 1);
        vm.prank(actor);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        // GENERAL RULE: settle() can never succeed in the same block as the locked-in target
        assertFalse(ok);
    }
}
